-- OR REPLACE keeps the view's grants; the columns are unchanged.
CREATE OR REPLACE VIEW "gitgazer"."users_view" WITH (security_barrier = true) AS (select "id", CASE WHEN (("gitgazer"."users"."id" in (select "user_id" from "github"."user-assignments" where "github"."user-assignments"."integration_id" = ANY ((SELECT github.integration_ids('admin'))::uuid[]))) or ("gitgazer"."users"."id" in (select "invited_by" from "gitgazer"."integration_invitations" where (("gitgazer"."integration_invitations"."status" <> 'accepted') and ("gitgazer"."integration_invitations"."integration_id" = ANY ((SELECT github.integration_ids('admin'))::uuid[]))))) or ("gitgazer"."users"."id" in (select "invitee_id" from "gitgazer"."integration_invitations" where (("gitgazer"."integration_invitations"."status" <> 'accepted') and ("gitgazer"."integration_invitations"."integration_id" = ANY ((SELECT github.integration_ids('admin'))::uuid[])))))) THEN "email" END as "email", "name", "picture", "github_login", CASE WHEN "gitgazer"."users"."id" in (select "user_id" from "github"."user-assignments" where "github"."user-assignments"."integration_id" = ANY ((SELECT github.integration_ids('viewer'))::uuid[])) THEN "last_active_at" END as "last_active_at" from "gitgazer"."users" where (("gitgazer"."users"."id" in (select "user_id" from "github"."user-assignments" where "github"."user-assignments"."integration_id" = ANY ((SELECT github.integration_ids('viewer'))::uuid[]))) or ("gitgazer"."users"."id" in (select "invited_by" from "gitgazer"."integration_invitations" where (("gitgazer"."integration_invitations"."status" <> 'accepted') and ("gitgazer"."integration_invitations"."integration_id" = ANY ((SELECT github.integration_ids('member'))::uuid[]))))) or ("gitgazer"."users"."id" in (select "invitee_id" from "gitgazer"."integration_invitations" where (("gitgazer"."integration_invitations"."status" <> 'accepted') and ("gitgazer"."integration_invitations"."integration_id" = ANY ((SELECT github.integration_ids('member'))::uuid[])))))));
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION github.integration_ids(text), github.signed_context() TO gitgazer_reader;
--> statement-breakpoint
GRANT SELECT ON gitgazer.users_view, github.user_assignments_view, gitgazer.integration_invitations_view TO gitgazer_reader;
